/**
 * Context handover plugin.
 *
 * Monitors an agent's context usage and interrupts the agent when it reaches a
 * configurable threshold (a fraction of the model's context limit). The
 * interrupt prompts the agent to write a handover document. When the document
 * is written, the plugin performs the handover in place: it compacts the same
 * session -- supplying the compaction summary itself, so the host makes no
 * model call -- and posts the continue prompt as the session's next message.
 * The session id never changes, so the TUI keeps its focus and no empty session
 * is left behind.
 *
 * The point of this plugin is to replace OpenCode's built-in compaction:
 * instead of an automatic lossy summary, the agent writes a deliberate handover
 * document and the session continues from it with a genuinely cleared context.
 *
 * The same cycle can be started by the user at any context level with the
 * `/handover` command; an optional note after the command becomes a
 * requirement for the document. The command only marks the session and asks the
 * agent for the document -- the context hook performs the handover -- so the
 * two entry points cannot drift apart.
 *
 * interrupt() is deliberately not used to stop the session: it cancels the
 * compaction and the continue prompt queued behind it (verified on 2.1.2). The
 * outgoing step is replaced with a stop note instead.
 *
 * Usage estimation must count the whole outgoing payload: system parts plus
 * every message part, including tool-call inputs and tool-result values, which
 * dominate real sessions. The model's context limit is resolved from the
 * OpenCode model catalog at setup (V2 hook events carry no limit), with the
 * event's limit as a legacy secondary source and a conservative fallback.
 *
 * Fail-open: every failure is logged and swallowed; the plugin never throws or
 * rejects, so a malformed event or a missing file never breaks the session.
 */

import { loadConfig, thresholdFor, type CtxHandoverConfig } from "./config.ts";
import { SessionTracker } from "./context-tracker.ts";
import { installIdleNudge } from "./idle-nudge.ts";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

/** The shape of the `context` hook event, narrowed to the fields we read. */
export type ContextEvent = {
  sessionID?: string;
  system?: { type: string; text: string }[];
  messages?: readonly { id?: string; role?: string; content?: unknown; metadata?: unknown }[];
  tools?: Record<string, unknown>;
  options?: Record<string, unknown>;
  // V2 hook events carry only { id, providerID, variant }; `limit` is the V1
  // legacy shape, kept as a secondary source when present.
  model?: { id?: string; providerID?: string; variant?: string; limit?: { context?: number; output?: number } };
  agent?: string;
};

/** The shape of the `compaction` hook event, narrowed to the fields we use. */
export type CompactionEvent = { sessionID?: string; result?: { summary?: string } };

/** The shape of the `prompt` hook event, narrowed to the fields we use. */
export type PromptHookEvent = { sessionID?: string; prompt?: { text?: string } };

/** A created compaction, narrowed to the id we read. */
export type CompactionResult = { id?: string; [key: string]: unknown };

/** The slice of `ctx.session` this plugin uses for the handover. */
export type SessionApi = {
  hook?: {
    (name: "context", cb: (e: ContextEvent) => void): Promise<unknown> | unknown;
    (name: "compaction", cb: (e: CompactionEvent) => void): Promise<unknown> | unknown;
    (name: "prompt", cb: (e: PromptHookEvent) => void): Promise<unknown> | unknown;
  };
  // Replaces the session's context with a summary. The plugin supplies that
  // summary through the compaction hook, so the host makes no model call.
  compact?: (input: { sessionID: string }) => Promise<CompactionResult> | CompactionResult;
  prompt?: (input: { sessionID: string; text: string; delivery?: "steer" | "queue" }) => Promise<unknown> | unknown;
  // Returns the session's current context as message objects; completed
  // assistant messages carry the provider-measured `tokens` (the real usage).
  context?: (input: { sessionID: string }) => Promise<unknown> | unknown;
  // The session's own record: `parentID` marks a subagent's child session,
  // which must not be told to continue the parent's work.
  get?: (input: { sessionID: string }) => Promise<unknown> | unknown;
};

/** The slice of `ctx.command` this plugin uses: registering one command. */
export type CommandApi = {
  transform?: (callback: (editor: CommandEditor) => void) => Promise<unknown> | unknown;
};

/** The command editor handed to a `ctx.command.transform` callback. */
export type CommandEditor = { add: (definition: HandoverCommand) => void };

/** The slice of OpenCode's setup context this plugin uses. */
export type SetupContext = {
  app?: { version?: string };
  location?: { directory?: string; project?: { id?: string; canonical?: string } };
  /** Plugin options from the object form in `opencode.jsonc`. */
  options?: Record<string, unknown>;
  session?: SessionApi;
  command?: CommandApi;
  /** The server's public event stream, for idle/busy transitions. */
  event?: {
    subscribe?: (options: { types?: string[]; signal?: AbortSignal }) => AsyncIterable<{
      type: string;
      properties?: { sessionID?: string; status?: { type?: string } };
      data?: { sessionID?: string };
    }>;
  };
  model?: {
    list?: () => Promise<{
      data?: { id?: string; providerID?: string; limit?: { context?: number; output?: number } }[];
    }>;
  };
};

/** Rough characters-per-token estimate used when the exact count is unavailable. */
const CHARS_PER_TOKEN = 4;

/** Fallback context limit (tokens) when neither catalog nor event reports one. */
const FALLBACK_CONTEXT_LIMIT = 200_000;

/**
 * Headroom (tokens) below which a work step is not worth dispatching: the
 * session hands over instead of starting a step it would have to cut short.
 */
const WORK_FLOOR = 4_096;

/** Fraction of the context limit a handover document may use. */
const DOC_BUDGET_FRACTION = 0.05;

/** Lower and upper bounds on the document budget (tokens). */
const DOC_BUDGET_MIN = 4_096;
const DOC_BUDGET_MAX = 32_768;

/**
 * The smallest document budget worth asking for. Below this the handover
 * cannot fit and the plugin falls back to a regular compaction instead.
 */
const MIN_DOC = 2_048;

/**
 * How many stop-and-write instructions one handover cycle may send before the
 * session falls back to a regular compaction. The instruction is not persisted
 * in the session history and a host prompt (a goal continuation) can arrive
 * between steps, so it is re-sent while the document is missing; the bound
 * keeps a non-compliant agent from spending the whole reserve before the
 * fallback fires.
 */
const MAX_DOC_INSTRUCTIONS = 3;

/**
 * The output budget a handover document may use, derived from the model's
 * context limit. A fixed ceiling keeps a 1M-token model from being asked for a
 * needlessly long document; the floor keeps small models usable.
 */
export function documentBudget(limit: number): number {
  return Math.min(DOC_BUDGET_MAX, Math.max(DOC_BUDGET_MIN, Math.floor(limit * DOC_BUDGET_FRACTION)));
}

/** How long to wait before retrying a catalog lookup that found no limit. */
const LIMIT_RETRY_MS = 10_000;

/**
 * Where diagnostics go. The stderr line is only visible when the server runs
 * without a TTY (e.g. `opencode serve`), so every line is additionally mirrored
 * to a file where an operator can find it: the OpenCode log directory, overridable
 * with OC_CTX_HANDOVER_LOG_FILE.
 */
const LOG_FILE =
  process.env.OC_CTX_HANDOVER_LOG_FILE ??
  path.join(os.homedir(), ".local", "share", "opencode", "log", "oc-ctx-handover.log");

/** Log one line: always to the log file, to stderr only off a TTY, never throwing. */
function log(message: string): void {
  try {
    fs.appendFileSync(LOG_FILE, `[oc-ctx-handover] ${new Date().toISOString()} ${message}\n`);
  } catch {
    // The mirror must never be the reason a session fails.
  }
  try {
    if (process.stderr.isTTY) return;
    process.stderr.write(`[oc-ctx-handover] ${message}\n`);
  } catch {
    // Logging must never be the reason a session fails.
  }
}

/** Approximate on-the-wire size of a JSON-serialized value, in characters. */
function wireLen(value: unknown): number {
  if (typeof value === "string") return value.length;
  if (value !== null && typeof value === "object") {
    const inner = (value as { value?: unknown }).value;
    if (typeof inner === "string") return inner.length;
  }
  try {
    return JSON.stringify(value)?.length ?? 0;
  } catch {
    return 0;
  }
}

/** Character weight of one message content part. */
function partChars(part: unknown): number {
  if (part === null || typeof part !== "object") return 0;
  const p = part as {
    text?: unknown;
    input?: unknown;
    result?: unknown;
    state?: { input?: unknown; output?: unknown; content?: unknown };
  };
  let chars = 0;
  if (typeof p.text === "string") chars += p.text.length;
  // V1 tool parts carry their payload outside `text`: the call's arguments in
  // `input`, the result's value in `result`.
  if (p.input !== undefined) chars += wireLen(p.input);
  if (p.result !== undefined) chars += wireLen(p.result);
  // V2 tool parts nest both under `state`: the call's arguments in
  // `state.input` and the result as `state.content` (an array of text parts),
  // with some builds using `state.output`.
  if (p.state !== null && typeof p.state === "object") {
    if (p.state.input !== undefined) chars += wireLen(p.state.input);
    if (p.state.output !== undefined) chars += wireLen(p.state.output);
    chars += contentChars(p.state.content);
  }
  return chars;
}

/** Character weight of a content value that may be a string or an array of parts. */
function contentChars(content: unknown): number {
  if (typeof content === "string") return content.length;
  if (!Array.isArray(content)) return 0;
  let chars = 0;
  for (const part of content) chars += partChars(part);
  return chars;
}

/**
 * Character weight of a tool part's *result* only. The measured anchor's own
 * token count already covers the call's arguments (they were generated by the
 * model), so counting them again would overstate the next request.
 */
function toolResultChars(part: unknown): number {
  if (part === null || typeof part !== "object") return 0;
  const p = part as {
    result?: unknown;
    state?: { output?: unknown; content?: unknown };
  };
  let chars = 0;
  if (p.result !== undefined) chars += wireLen(p.result);
  if (p.state !== null && typeof p.state === "object") {
    if (p.state.output !== undefined) chars += wireLen(p.state.output);
    chars += contentChars(p.state.content);
  }
  return chars;
}

/** Estimate token usage from system parts, message contents, and tool schemas. */
function estimateTokens(
  system?: { type: string; text: string }[],
  messages?: readonly { content?: unknown }[],
  tools?: unknown,
): number {
  let chars = 0;
  for (const part of system ?? []) {
    if (part?.text) chars += part.text.length;
  }
  for (const message of messages ?? []) {
    const content = message.content;
    if (typeof content === "string") {
      chars += content.length;
    } else if (Array.isArray(content)) {
      for (const part of content) {
        chars += partChars(part);
      }
    }
  }
  // Tool schemas are part of every request and can be tens of thousands of
  // tokens (an MCP server's tool set); the context estimate must include them.
  chars += wireLen(tools);
  return Math.ceil(chars / CHARS_PER_TOKEN);
}

/** Provider-measured token usage as stored on a completed assistant message. */
type TokenUsage = {
  input?: number;
  output?: number;
  reasoning?: number;
  cache?: { read?: number; write?: number };
};

/**
 * Find the newest assistant message that carries provider-measured `tokens` and
 * return the measured context size (input + cache read + cache write) plus the
 * character count of the parts added after that message (the newest step's tool
 * results, not yet measured). Returns null when no measured usage is present.
 *
 * The measured size is the same ground truth OpenCode's built-in compaction and
 * the UI percentage use, so anchoring on it keeps this trigger accurate where a
 * chars-per-token estimate undercounts dense code/JSON.
 */
function measuredAnchor(
  messages: unknown,
  modelProviderID?: string,
): { measured: number; deltaChars: number } | null {
  if (!Array.isArray(messages)) return null;
  let anchorIndex = -1;
  let measured = 0;
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i] as {
      role?: string;
      type?: string;
      model?: { providerID?: string };
      tokens?: TokenUsage;
    } | null;
    if (!m) continue;
    const isAssistant = m.role === "assistant" || m.type === "assistant";
    const t = m.tokens;
    if (!isAssistant || t === null || typeof t !== "object") continue;
    // Trust only the current provider's counts: a mid-session model switch
    // leaves another tokenizer's numbers behind (mirrors hasMeasuredPrompt).
    if (modelProviderID !== undefined && m.model?.providerID !== modelProviderID) continue;
    const cache = t.cache ?? {};
    // input + cache is the anchor call's prompt; output + reasoning is its reply,
    // which is part of the next call's context (mirrors estimatePrompt).
    measured =
      (typeof t.input === "number" ? t.input : 0) +
      (typeof cache.read === "number" ? cache.read : 0) +
      (typeof cache.write === "number" ? cache.write : 0) +
      (typeof t.output === "number" ? t.output : 0) +
      (typeof t.reasoning === "number" ? t.reasoning : 0);
    anchorIndex = i;
    break;
  }
  if (anchorIndex === -1) return null;
  // The anchor's own token count covers its prompt and generated output, but
  // not the tool results added after it -- in V2 those are carried inside the
  // same assistant message (`state.content`), so they are not messages "after"
  // the anchor and the delta loop below would miss them entirely.
  const anchorContent = (messages[anchorIndex] as { content?: unknown }).content;
  if (Array.isArray(anchorContent)) {
    let anchorResultChars = 0;
    for (const part of anchorContent) anchorResultChars += toolResultChars(part);
    measured += Math.ceil(anchorResultChars / CHARS_PER_TOKEN);
  }
  let deltaChars = 0;
  for (let i = anchorIndex + 1; i < messages.length; i++) {
    const content = (messages[i] as { content?: unknown }).content;
    if (typeof content === "string") deltaChars += content.length;
    else if (Array.isArray(content)) for (const part of content) deltaChars += partChars(part);
  }
  return { measured, deltaChars };
}

/** The handover document's mtime, or null when it does not exist. */
function handoverFileMtime(file: string): number | null {
  try {
    return fs.statSync(file).mtimeMs;
  } catch {
    return null;
  }
}

/**
 * Whether the handover document was written since the interrupt: either it did
 * not exist then, or its mtime changed. A document left behind by an earlier
 * session in the same directory is not this session's handover.
 */
function handoverFileRewritten(file: string, mtimeAtInterrupt: number | null): boolean {
  const current = handoverFileMtime(file);
  if (current === null) return false;
  return mtimeAtInterrupt === null || current !== mtimeAtInterrupt;
}

/** Whether the document exists and was last written within `maxAgeDays`. */
function handoverFileIsRecent(file: string, maxAgeDays: number): boolean {
  const mtime = handoverFileMtime(file);
  if (mtime === null) return false;
  return Date.now() - mtime <= maxAgeDays * 24 * 60 * 60 * 1000;
}

/**
 * Whether the session has no history yet. The first step of a new session
 * carries at most the user's opening message; an assistant reply or a
 * compaction means work is already under way and the document is no longer
 * news to this session.
 */
