/**
 * The note that replaces the outgoing step when a regular compaction is the
 * last resort: there is no handover document to continue from.
 */
function fallbackStopNote(): { role: string; content: { type: string; text: string }[] } {
  return {
    role: "user",
    content: [
      {
        type: "text",
        text:
          `This session is being compacted to recover from context exhaustion; no handover document could be written. ` +
          `Stop now and do not take further action in this session.`,
      },
    ],
  };
}

/**
 * Perform the handover in place: compact the session (the compaction hook
 * supplies the summary, so the host makes no model call) and post the continue
 * prompt back into the same session. The session id is unchanged, so the TUI
 * keeps its focus and no empty session is left behind.
 *
 * interrupt() is not called: it cancels the queued compaction and prompt.
 *
 * Fail-open: a failure is logged and leaves the cycle pending so a later step
 * retries it; a continue prompt that failed is retried when the compaction
 * lands.
 */
async function performInPlaceHandover(
  sessionApi: SessionApi,
  tracker: SessionTracker,
  sessionID: string,
  handoverFile: string,
): Promise<void> {
  if (tracker.isHandoverInFlight(sessionID)) return;
  tracker.beginHandover(sessionID);
  try {
    if (typeof sessionApi.compact !== "function" || typeof sessionApi.prompt !== "function") {
      throw new Error("ctx.session.compact/prompt is unavailable in this build; cannot hand over");
    }

    const compaction = await sessionApi.compact({ sessionID });
    const compactionID = compaction?.id;
    if (typeof compactionID !== "string" || compactionID === "") {
      throw new Error("session.compact returned no id");
    }
    tracker.setPendingCompaction(sessionID, compactionID);
    log(`handover: compaction ${compactionID} queued for session ${sessionID}`);

    await postContinuePrompt(sessionApi, tracker, sessionID, handoverFile);
    log(`handover: session ${sessionID} continues in place from ${handoverFile}`);
  } catch (error) {
    // Leave the cycle pending so a later step retries.
    log(`handover failed (will retry on a later step): ${String(error)}`);
  } finally {
    tracker.endHandover(sessionID);
  }
}

/**
 * Last-resort recovery when not even a minimal handover document fits: ask for
 * a regular compaction. The plugin's compaction hook leaves it alone (no
 * pending handover id is set), so the host writes its own summary. Attempted
 * once per session: a second request would only fail again at the same wall.
 */
async function performFallbackCompaction(
  sessionApi: SessionApi,
  tracker: SessionTracker,
  sessionID: string,
): Promise<void> {
  if (tracker.isFallbackAttempted(sessionID)) return;
  tracker.markFallbackAttempted(sessionID);
  try {
    if (typeof sessionApi.compact !== "function") {
      log("handover impossible and ctx.session.compact is unavailable; the session cannot continue");
      return;
    }
    const compaction = await sessionApi.compact({ sessionID });
    log(
      `handover impossible: a regular compaction ${compaction?.id ?? ""} was queued for session ${sessionID}`,
    );
  } catch (error) {
    log(`fallback compaction failed: ${String(error)}`);
  }
}

/**
 * The compaction hook. When the plugin's own handover compacts a session the
 * summary is the plugin's text rather than a model-written one: setting
 * `result` makes the host skip the compaction model request entirely. A
 * compaction the plugin did not ask for (the user's own /compact) is left
 * alone.
 */
export function createCompactionHandler(cfg: CtxHandoverConfig, tracker: SessionTracker) {
  return (event: CompactionEvent): void => {
    const sessionID = event?.sessionID;
    if (typeof sessionID !== "string" || sessionID === "") return;
    if (tracker.getPendingCompactionID(sessionID) === null) return;
    event.result = {
      summary:
        `The session was handed over to a fresh context. The earlier work, the state it was left in, and the ` +
        `next steps are recorded in the handover document at ${cfg.handoverFile}.`,
    };
  };
}

/** Resolve the handover document against the session's directory. */
function resolveHandoverFile(cfg: CtxHandoverConfig, sessionDir?: string): string {
  return path.isAbsolute(cfg.handoverFile)
    ? cfg.handoverFile
    : path.resolve(sessionDir ?? process.cwd(), cfg.handoverFile);
}

/**
 * The stop-and-write instruction. Every way into a handover (the threshold, the
 * work floor, the `/handover` command) shares these directives, so the document
 * is written the same way however the handover started; only the opening
 * sentence says why.
 */
function stopInstruction(
  handoverFile: string,
  opening: string,
  note?: string,
  budgetTokens?: number,
  mode: "continue" | "leave" = "continue",
): string {
  const trimmedNote = note?.trim() ?? "";
  // The note goes before the directives and is framed as document content: a
  // note that read like further instructions would compete with "stop now".
  const capture = trimmedNote === "" ? "" : `The handover document must capture this: ${trimmedNote}. `;
  // Name the budget the cap actually enforces, so the model can size the
  // document instead of discovering the limit by being cut off mid-write.
  const budget =
    budgetTokens !== undefined && budgetTokens > 0
      ? `The handover document must fit in ${budgetTokens} output tokens. Write it now, within that budget. `
      : "";
  // Whether the session continues in place or is left: the closing sentence
  // tells the agent what happens next, so it neither promises a continuation
  // that will not come nor keeps working after a leave.
  const afterwards =
    mode === "leave"
      ? "The user is leaving this session; do not continue the work yourself. " +
        "The next session will read the document and pick the work up from there."
      : "This session continues from it with a fresh context " + "and picks the work up there.";
  return (
    opening +
    capture +
    budget +
    "Stop the task you are on now. Do not finish the current step, do not start another, and " +
    `run no tools except the one that writes the file. Your next action must be writing a handover document to ${handoverFile}. ` +
    `Everything unfinished — the current step, what you were about to do, and the next steps — goes ` +
    `in that document, not into more work. ` +
    afterwards
  );
}

/**
 * The slice of an OpenCode command invocation this plugin reads. The host
 * passes the user's prompt (the text typed after `/handover`), so the command
 * accepts an optional note for what the document must capture.
 */
export type HandoverCommandInvocation = {
  sessionID: string;
  prompt?: { text?: string };
  delivery?: "steer" | "queue";
};

/** A command definition, as registered through `ctx.command.transform`. */
export type HandoverCommand = {
  name: string;
  description: string;
  execute: (input: HandoverCommandInvocation) => Promise<void>;
};

/**
 * The `/handover` command's text: a leading `--continue` or `--leave` flag,
 * then an optional note for the document. Without a flag the session is left
 * after the document; `--continue` asks for the in-place handover instead.
 */
export function parseHandoverPrompt(text: string | undefined): { mode: "continue" | "leave"; note: string } {
  const trimmed = text?.trim() ?? "";
  const match = /^(--continue|--leave)(?:\s+([\s\S]*))?$/.exec(trimmed);
  if (match === null) return { mode: "leave", note: trimmed };
  return { mode: match[1] === "--continue" ? "continue" : "leave", note: (match[2] ?? "").trim() };
}

