        // for a regular compaction instead (once; the second request would
        // fail at the same wall).
        if (docRoom < MIN_DOC) {
          await fallBackToRegularCompaction(
            `only ${headroomToLimit} tokens of headroom remain; a handover document does not fit, falling back to a regular compaction`,
          );
          return;
        }
        tracker.setInterrupted(sessionID, handoverFileMtime(HANDOVER_FILE));
        tracker.noteDocInstruction(sessionID);
        capOutput(event.options, docRoom);
        // Interrupt the agent: tell it to write a handover document. The
        // trigger is normally the threshold; when it is the work floor instead
        // the session is still just short of the threshold, so say "about to".
        const reached = fraction >= threshold;
        event.messages = [
          ...(event.messages ?? []),
          {
            role: "user",
            content: [
              {
                type: "text",
                text: stopInstruction(
                  HANDOVER_FILE,
                  reached
                    ? `Your context is nearly full: ${Math.round(fraction * 100)}% of the context limit is used. `
                    : `Your context is nearly full: only ${headroomToCeiling} tokens remain before the handover ceiling. `,
                  undefined,
                  docRoom,
                ),
              },
            ],
          },
        ];
        log(
          reached
            ? `usage ${usage} >= threshold ${Math.round(threshold * 100)}% of ${limit}; interrupting session ${sessionID}`
            : `only ${headroomToCeiling} tokens of headroom left (work floor ${WORK_FLOOR}); interrupting session ${sessionID}`,
        );
        return;
      }

      // Normal step: bound this decode so it cannot carry the session past
      // the threshold. The host honours this option, so the step ends at the
      // ceiling even if the model would happily generate far more.
      capOutput(event.options, headroomToCeiling);
    } catch (error) {
      // Fail-open: never let a hook failure break the session.
      log(`context hook failed open: ${String(error)}`);
    }
  }

  return { hook };
}

/** The plugin OpenCode registers. */
export const plugin = {
  id: "oc-ctx-handover",
  async setup(ctx: SetupContext): Promise<void | (() => void)> {
    const cfg = loadConfig(process.env, ctx?.options);
    if (!cfg.enabled) {
      log("disabled: set OC_CTX_HANDOVER_DISABLED=0 to enable context monitoring");
      return;
    }

    const session = ctx?.session;
    if (session === undefined || typeof session.hook !== "function") {
      log("no ctx.session.hook on this build; not registering the context hook");
      return;
    }

    // Record which session operations this build exposes so a missing
    // compact/prompt/context is observable in the log rather than silent.
    const have = (name: "compact" | "prompt" | "context" | "get") =>
      session[name] === undefined ? "missing" : typeof session[name] === "function" ? "ok" : "not-a-function";
    log(
      `session api: compact=${have("compact")} prompt=${have("prompt")} context=${have("context")} get=${have("get")}`,
    );

    const tracker = new SessionTracker();
    const limitMap = await readCatalogLimits(ctx);
    const handler = createHandler(cfg, tracker, limitMap, session, ctx?.location?.directory, () =>
      readCatalogLimits(ctx, false),
    );
    // The compaction hook supplies the handover summary, so the handover's
    // compaction makes no model call. It must be registered before the context
    // hook can request a compaction.
    try {
      await session.hook("compaction", createCompactionHandler(cfg, tracker));
      log("compaction hook registered");
    } catch (error) {
      log(`registering the compaction hook failed: ${String(error)}`);
    }
    // The command is a second entry point into the same cycle. A build without
    // the command domain, or a failing registration, must not cost the session
    // its handover machinery, so it is registered on its own and never fatal.
    try {
      const commands = ctx?.command;
      if (commands === undefined || typeof commands.transform !== "function") {
        log("no ctx.command.transform on this build; /handover is not registered");
      } else {
        const command = createHandoverCommand(cfg, tracker, session, ctx?.location?.directory);
        await commands.transform.call(commands, (editor: CommandEditor) => editor.add(command));
        log("handover command registered");
      }
    } catch (error) {
      log(`registering the handover command failed: ${String(error)}`);
    }
    try {
      await session.hook("context", handler.hook);
      log("context hook registered");
    } catch (error) {
      log(`registering the context hook failed: ${String(error)}`);
    }

    // The idle nudge persists the session's knowledge before its cache goes
    // stale: a session that has waited for the user for a while is asked to
    // refresh the handover document. It is independent of the context hook:
    // failing to install it must not cost the session its handover machinery.
    const hook = session.hook;
    let stopIdleNudge: (() => void) | null = null;
    try {
      stopIdleNudge = await installIdleNudge({
        seconds: cfg.idleNudgeSeconds,
        handoverFile: resolveHandoverFile(cfg, ctx?.location?.directory),
        locationDirectory: ctx?.location?.directory,
        session: {
          prompt: session.prompt,
          get: session.get,
          context: session.context,
          hook:
            hook === undefined
              ? undefined
              : (name, callback) => hook(name as "prompt", callback as (e: PromptHookEvent) => void),
        },
        event: ctx?.event,
        isHandoverBusy: (sessionID) =>
          tracker.isHandoverPending(sessionID) || tracker.isHandoverInFlight(sessionID),
        log,
      });
      if (stopIdleNudge !== null) log(`idle nudge active: ${cfg.idleNudgeSeconds}s`);
    } catch (error) {
      log(`installing the idle nudge failed: ${String(error)}`);
    }
    return stopIdleNudge ?? undefined;
  },
};
